from pysat.solvers import Solver

n = 27
length = 2 * n

solver = Solver(name='m22')

def var(v, i):
    return v * 1000 + i

for v in range(1, n + 1):
    clause = []
    for i in range(length - v - 1):
        clause.append(var(v, i))
    solver.add_clause(clause)
    for i in range(length - v - 1):
        for j in range(i + 1, length - v - 1):
            solver.add_clause([-var(v, i), -var(v, j)])

for p in range(length):
    clause = []
    for v in range(1, n + 1):
        if p <= length - v - 2:
            clause.append(var(v, p))
        if p >= v + 1:
            clause.append(var(v, p - v - 1))
    solver.add_clause(clause)
    for i in range(len(clause)):
        for j in range(i + 1, len(clause)):
            solver.add_clause([-clause[i], -clause[j]])

if solver.solve():
    model = solver.get_model()
    seq = [0] * length
    for m in model:
        if m > 0:
            v = m // 1000
            i = m % 1000
            seq[i] = v
            seq[i + v + 1] = v
    print(seq)
else:
    print("UNSAT")
